cat <<'EOF' | singular -q
ring r = 0,(x1,x2,x3,x4,x5,x6),dp;
ideal I =
x2*x4 + x3*x6,
x3*x5 + x1*x6,
x1*x2 - x2*x5 + x3*x5 - x5*x6,
x2*x3 + x2*x4 + x2*x6 + x6^2,
x3^2 + x3*x4 + x3*x6 - x4*x6,
x1*x3 + x1*x4 + x4*x5 + x1*x6;
// check if I is prime
def rs = quotient(I, I);
// test non-zerodivisor: l is NZD iff (I:l) == I, i.e. quotient(I,l) == I... 
// Actually (I : l) = l^{-1} I. Use sat or quotient.
ideal l1 = x1;
ideal q1 = quotient(I, l1);   // (I : x1)
dim(q1);
EOF

